/** static void FillTentTrainerParty_(u16 trainerId, u8 firstMonId, u8 monCount) */
export function FillTentTrainerParty_(trainerId: any, firstMonId: any, monCount: any): any {
  let i, j;
      let chosenMonIndices: any = [];
      let friendship: any = null;
      let level: any = SetTentPtrsGetLevel();
      let fixedIV: any = 0;
      let bfMonCount: any = null;
      let monSet: any = NULL;
      let otID: any = 0;
      let monId: any = null;

      monSet = gFacilityTrainers[gTrainerBattleOpponent_A].monSet;

      bfMonCount = 0;
      monId = monSet[bfMonCount];
      while (monId != 0xFFFF)
      {
          bfMonCount++;
          monId = monSet[bfMonCount];
          if (monId == 0xFFFF)
              break;
      }

      i = 0;
      otID = Random32();
      while (i != monCount)
      {
          let monId: any = monSet[Random() % bfMonCount];

           
          for (j = 0; j < i + firstMonId; j++)
          {
              if (GetMonData(gEnemyParty[j], MON_DATA_SPECIES, NULL) == gFacilityTrainerMons[monId].species)
                  break;
          }
          if (j != i + firstMonId)
              continue;

           
          for (j = 0; j < i + firstMonId; j++)
          {
              if (GetMonData(gEnemyParty[j], MON_DATA_HELD_ITEM, NULL) != (0)
               && GetMonData(gEnemyParty[j], MON_DATA_HELD_ITEM, NULL) == gBattleFrontierHeldItems[gFacilityTrainerMons[monId].itemTableId])
                  break;
          }
          if (j != i + firstMonId)
              continue;

           
           
          for (j = 0; j < i; j++)
          {
              if (chosenMonIndices[j] == monId)
                  break;
          }
          if (j != i)
              continue;

          chosenMonIndices[i] = monId;

           
          CreateMonWithEVSpreadNatureOTID(gEnemyParty[i + firstMonId],
                                               gFacilityTrainerMons[monId].species,
                                               level,
                                               gFacilityTrainerMons[monId].nature,
                                               fixedIV,
                                               gFacilityTrainerMons[monId].evSpread,
                                               otID);

          friendship = (255);
           
          for (j = 0; j < (4); j++)
          {
              SetMonMoveSlot(gEnemyParty[i + firstMonId], gFacilityTrainerMons[monId].moves[j], j);
              if (gFacilityTrainerMons[monId].moves[j] == (218))
                  friendship = 0;   
          }

          SetMonData(gEnemyParty[i + firstMonId], MON_DATA_FRIENDSHIP,friendship);
          SetMonData(gEnemyParty[i + firstMonId], MON_DATA_HELD_ITEM,gBattleFrontierHeldItems[gFacilityTrainerMons[monId].itemTableId]);

           
           
          i++;
      }
}

/** u8 FacilityClassToGraphicsId(u8 facilityClass) */
export function FacilityClassToGraphicsId(facilityClass: any): any {
  let trainerObjectGfxId: any = null;
      let i: any = null;

       
      for (i = 0; i < ARRAY_COUNT(gTowerMaleFacilityClasses); i++)
      {
          if (gTowerMaleFacilityClasses[i] == facilityClass)
              break;
      }
      if (i != ARRAY_COUNT(gTowerMaleFacilityClasses))
      {
          trainerObjectGfxId = gTowerMaleTrainerGfxIds[i];
          return trainerObjectGfxId;
      }

       
      for (i = 0; i < ARRAY_COUNT(gTowerFemaleFacilityClasses); i++)
      {
          if (gTowerFemaleFacilityClasses[i] == facilityClass)
              break;
      }
      if (i != ARRAY_COUNT(gTowerFemaleFacilityClasses))
      {
          trainerObjectGfxId = gTowerFemaleTrainerGfxIds[i];
          return trainerObjectGfxId;
      }
      else
      {
          return (7);
      }
}

/** bool32 ValidateBattleTowerRecord(u8 recordId) */
export function ValidateBattleTowerRecord(recordId: any): any {
  let i: any = null;
      let record: any = (gSaveBlock2Ptr.frontier.towerRecords[recordId]);
      let checksum: any = 0;
      let hasData: any = 0;
      for (i = 0; i < 0 / 0; i++)
      {
          checksum += record[i];
          hasData |= record[i];
      }

      if (checksum == 0 && hasData == 0)
      {
          return FALSE;
      }
      else if (gSaveBlock2Ptr.frontier.towerRecords[recordId].checksum != checksum)
      {
          ClearBattleTowerRecord(gSaveBlock2Ptr.frontier.towerRecords[recordId]);
          return FALSE;
      }
      else
      {
          return TRUE;
      }
}

